-- Internal user-to-user messages; stored privately in the non-exposed rentall schema.
CREATE TABLE IF NOT EXISTS rentall."Mensagens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AnuncioId" integer NOT NULL REFERENCES rentall."Anuncios"(id) ON DELETE CASCADE,
    "RemetenteId" text NOT NULL REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
    "DestinatarioId" text NOT NULL REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
    "Texto" varchar(2000) NOT NULL,
    "CriadaEm" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "CK_Mensagens_Participantes" CHECK ("RemetenteId" <> "DestinatarioId"),
    CONSTRAINT "CK_Mensagens_Tamanho" CHECK (char_length("Texto") BETWEEN 1 AND 2000)
);
CREATE INDEX IF NOT EXISTS "IX_Mensagens_Rem_Dest" ON rentall."Mensagens" ("RemetenteId", "DestinatarioId", "AnuncioId", "CriadaEm");
CREATE INDEX IF NOT EXISTS "IX_Mensagens_Dest" ON rentall."Mensagens" ("DestinatarioId", "AnuncioId", "CriadaEm");
REVOKE ALL ON rentall."Mensagens" FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE rentall."Mensagens_Id_seq" FROM PUBLIC, anon, authenticated;
